using System.Diagnostics;
using Microsoft.Playwright;

namespace GlpiPilot.Core;

public sealed partial class BrowserService
{
    // Observe only the native preferences and result requests in the selected
    // GLPI frame. An active server request is work in progress, not an expired
    // UI locator. No request, endpoint or retry is generated by this observer.
    private sealed class ColumnPreparationActivity : IDisposable
    {
        private sealed class RequestState(long sequence, long chain, IFrame frame, bool command)
        {
            public long Sequence { get; } = sequence;
            public long Chain { get; } = chain;
            public IFrame Frame { get; } = frame;
            public bool Command { get; } = command;
            public bool Pending { get; set; } = true;
            public string? Failure { get; set; }
        }

        private sealed class ResponseWaiter(long sequence, Func<IResponse, bool> predicate)
        {
            public long Sequence { get; } = sequence;
            public Func<IResponse, bool> Predicate { get; } = predicate;
            public TaskCompletionSource<IResponse> Completion { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        }

        private readonly IPage _page;
        private readonly IFrame _tableFrame;
        private readonly string _origin;
        private readonly string _listPath;
        private readonly TimeSpan _inactivity;
        private readonly Action<string>? _report;
        private readonly object _gate = new();
        private readonly Dictionary<IRequest, RequestState> _requests = new(ReferenceEqualityComparer.Instance);
        private readonly List<ResponseWaiter> _waiters = [];
        private IFrame? _preferencesFrame;
        private bool _includeTableRequests;
        private long _sequence;
        private long _progressAt = Stopwatch.GetTimestamp();
        private long _noticeAt = Stopwatch.GetTimestamp();
        private string _signature = "";
        private string _phase = "lecture de la fenêtre des colonnes";
        private InvalidOperationException? _failure;
        private bool _disposed;

        public ColumnPreparationActivity(IPage page, IFrame tableFrame, string origin, int inactivitySeconds, Action<string>? report)
        {
            if (tableFrame.Page != page || !Uri.TryCreate(origin, UriKind.Absolute, out var uri)
                || uri.Scheme is not ("https" or "http") || uri.UserInfo.Length != 0)
                throw new ArgumentException("Le contexte de préparation des colonnes n’est pas valide.");
            _page = page; _tableFrame = tableFrame; _origin = uri.GetLeftPart(UriPartial.Authority);
            _listPath = new Uri(tableFrame.Url).AbsolutePath;
            _inactivity = TimeSpan.FromSeconds(Math.Clamp(inactivitySeconds, 5, 600));
            _report = report;
            page.Request += OnRequest;
            page.Response += OnResponse;
            page.RequestFinished += OnRequestFinished;
            page.RequestFailed += OnRequestFailed;
        }

        public string Phase { get { lock (_gate) return _phase; } }
        public bool HasPendingRequest { get { lock (_gate) return _requests.Values.Any(request => request.Pending && Owned(request)); } }

        public void BeginPhase(string phase, bool includeTableRequests = false)
        {
            ThrowIfFailed();
            lock (_gate)
            {
                _phase = phase; _signature = ""; _includeTableRequests = includeTableRequests;
                _progressAt = _noticeAt = Stopwatch.GetTimestamp();
            }
            _report?.Invoke("Préparation des colonnes · " + phase + "…");
        }

        public void BindPreferencesFrame(IFrame frame)
        {
            if (frame.Page != _page || frame.ParentFrame != _tableFrame || frame.IsDetached
                || frame.Url != "about:blank" && !LocalAddress(frame.Url, out _))
                throw new InvalidOperationException("Le cadre personnel des colonnes n’appartient plus au contexte GLPI vérifié.");
            lock (_gate)
            {
                if (_preferencesFrame == frame) return;
                if (_preferencesFrame is not null && _requests.Values.Any(request => request.Frame == _preferencesFrame && request.Command && request.Pending))
                    throw new InvalidOperationException("La fenêtre personnelle a été remplacée pendant un ajout non confirmé. Aucun ajout n’est renvoyé.");
                _preferencesFrame = frame;
                _progressAt = Stopwatch.GetTimestamp();
                foreach (var request in _requests.Values.Where(request => request.Frame == frame && request.Failure is not null))
                    Fail(request.Failure!);
            }
            ThrowIfFailed();
        }

        private bool Owned(RequestState request) => request.Frame == _preferencesFrame
            || _includeTableRequests && request.Frame == _tableFrame;

        public void Observe(string signature)
        {
            lock (_gate)
            {
                if (_signature == signature) return;
                _signature = signature;
                _progressAt = Stopwatch.GetTimestamp();
            }
        }

        public void ThrowIfFailed()
        {
            lock (_gate)
            {
                if (_failure is not null) throw _failure;
                if (_page.IsClosed || _tableFrame.IsDetached)
                    throw new InvalidOperationException("La fenêtre GLPI a été fermée ou son cadre remplacé pendant la préparation des colonnes.");
            }
        }

        public bool CanWait
        {
            get
            {
                ThrowIfFailed();
                string? notice = null;
                bool canWait;
                lock (_gate)
                {
                    var active = _requests.Values.Any(request => request.Pending && Owned(request));
                    canWait = active || Stopwatch.GetElapsedTime(_progressAt) < _inactivity;
                    if (active && Stopwatch.GetElapsedTime(_noticeAt) >= TimeSpan.FromSeconds(5))
                    {
                        _noticeAt = Stopwatch.GetTimestamp();
                        notice = $"Préparation des colonnes · {_phase} : une requête GLPI est encore en cours. Attendre ou annuler.";
                    }
                }
                if (notice is not null) _report?.Invoke(notice);
                return canWait;
            }
        }

        private bool LocalAddress(string url, out Uri? address)
        {
            address = Uri.TryCreate(url, UriKind.Absolute, out var uri) && uri.Scheme is "https" or "http"
                && uri.UserInfo.Length == 0 && string.Equals(uri.GetLeftPart(UriPartial.Authority), _origin, StringComparison.OrdinalIgnoreCase)
                ? uri : null;
            return address is not null;
        }

        private static bool PreferencesPath(string path) => path.EndsWith("/front/displaypreference.form.php", StringComparison.Ordinal);
        private static bool CommandPath(string path) => PreferencesPath(path) || path.EndsWith("/ajax/displaypreference.php", StringComparison.Ordinal);

        private static string? QueryValue(Uri address, string name)
        {
            var matches = address.Query.TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries)
                .Select(part => part.Split('=', 2))
                .Where(pair => Uri.UnescapeDataString(pair[0].Replace('+', ' ')) == name).ToArray();
            return matches.Length == 1 ? Uri.UnescapeDataString((matches[0].Length == 2 ? matches[0][1] : "").Replace('+', ' ')) : null;
        }

        private bool IsRelevant(IRequest request, Uri address, out IFrame? frame)
        {
            frame = null;
            if (request.ResourceType is not ("document" or "xhr" or "fetch")) return false;
            try { frame = request.Frame; }
            catch (PlaywrightException) { return false; }
            if (frame.Page != _page || frame != _tableFrame && frame.ParentFrame != _tableFrame) return false;
            var path = address.AbsolutePath;
            if (frame == _tableFrame)
                return _includeTableRequests && (request.IsNavigationRequest && path == _listPath
                    || path.EndsWith("/ajax/search.php", StringComparison.Ordinal));
            // A direct child is accepted only for native preferences. Requests
            // from unrelated frames, assets and background polling do not keep
            // this operation alive or supply its success/failure evidence.
            if (PreferencesPath(path)) return frame == _preferencesFrame || request.Method == "GET" && QueryValue(address, "itemtype") == "Ticket";
            if (frame != _preferencesFrame) return false;
            if (!LocalAddress(frame.Url, out var frameAddress) || !PreferencesPath(frameAddress!.AbsolutePath)) return false;
            return path.EndsWith("/ajax/displaypreference.php", StringComparison.Ordinal)
                || path.EndsWith("/ajax/common.tabs.php", StringComparison.Ordinal)
                    && QueryValue(address, "_itemtype") == "DisplayPreference" && QueryValue(address, "displaytype") == "Ticket";
        }

        private void OnRequest(object? sender, IRequest request)
        {
            lock (_gate)
            {
                if (_disposed || _failure is not null) return;
                if (request.RedirectedFrom is { } previous && _requests.TryGetValue(previous, out var redirected))
                {
                    redirected.Pending = false;
                    if (!LocalAddress(request.Url, out var destination) || !IsRelevant(request, destination!, out _))
                    {
                        redirected.Failure = "GLPI a redirigé la préparation des colonnes hors de sa fenêtre native. Vérifier la session dans le navigateur.";
                        if (Owned(redirected)) Fail(redirected.Failure);
                        return;
                    }
                    _requests[request] = new(++_sequence, redirected.Chain, redirected.Frame, redirected.Command);
                    if (Owned(redirected)) _progressAt = Stopwatch.GetTimestamp();
                    return;
                }
                if (!LocalAddress(request.Url, out var address) || !IsRelevant(request, address!, out var frame)) return;
                var sequence = ++_sequence;
                var state = new RequestState(sequence, sequence, frame!, request.Method == "POST" && CommandPath(address!.AbsolutePath));
                _requests[request] = state;
                if (Owned(state)) _progressAt = Stopwatch.GetTimestamp();
            }
        }

        private void OnResponse(object? sender, IResponse response)
        {
            lock (_gate)
            {
                if (_disposed || !_requests.TryGetValue(response.Request, out var request)) return;
                if (response.Status >= 400)
                    request.Failure = response.Status is 401 or 403
                        ? $"GLPI a refusé la préparation des colonnes (HTTP {response.Status}, {_phase}). Vérifier la connexion et les droits de la vue personnelle."
                        : $"GLPI a renvoyé une erreur pendant la préparation des colonnes (HTTP {response.Status}, {_phase}). Aucun ajout n’est renvoyé automatiquement.";
                if (!Owned(request)) return;
                _progressAt = Stopwatch.GetTimestamp();
                if (request.Failure is not null) Fail(request.Failure);
                foreach (var waiter in _waiters)
                {
                    if (request.Sequence <= waiter.Sequence) continue;
                    try { if (waiter.Predicate(response)) waiter.Completion.TrySetResult(response); }
                    catch (Exception error) when (error is PlaywrightException or InvalidOperationException)
                    {
                        // A navigation can retire a frame while its response
                        // arrives. An event callback must not crash the host or
                        // turn that unverified response into a success.
                        Fail("La réponse GLPI ne peut plus être rattachée à la fenêtre personnelle vérifiée. Aucun ajout n’est renvoyé.");
                    }
                }
            }
        }

        private void OnRequestFinished(object? sender, IRequest request)
        {
            lock (_gate)
            {
                if (_disposed || !_requests.TryGetValue(request, out var state)) return;
                state.Pending = false;
                if (Owned(state)) _progressAt = Stopwatch.GetTimestamp();
            }
        }

        private void OnRequestFailed(object? sender, IRequest request)
        {
            lock (_gate)
            {
                if (_disposed || !_requests.TryGetValue(request, out var state)) return;
                state.Pending = false;
                if (Owned(state)) _progressAt = Stopwatch.GetTimestamp();
                var failure = request.Failure ?? "";
                // Replacing an iframe can cancel its old GET normally. A POST
                // interrupted this way has an unknown outcome and must stop.
                if (!state.Command && (failure.Contains("ERR_ABORTED", StringComparison.OrdinalIgnoreCase)
                    || failure.Contains("NS_BINDING_ABORTED", StringComparison.OrdinalIgnoreCase))) return;
                state.Failure = $"La requête GLPI a été interrompue pendant la préparation des colonnes ({_phase}). Vérifier la connexion ; aucun ajout n’est renvoyé automatiquement.";
                if (Owned(state)) Fail(state.Failure);
            }
        }

        private void Fail(string message) => _failure ??= new InvalidOperationException(message);

        public async Task<IResponse> RunAndWaitForResponseAsync(Func<Task> action, Func<IResponse, bool> predicate, CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested();
            ThrowIfFailed();
            ResponseWaiter waiter;
            lock (_gate) { waiter = new(_sequence, predicate); _waiters.Add(waiter); }
            Task actionTask;
            try { actionTask = action(); }
            catch { lock (_gate) _waiters.Remove(waiter); throw; }
            // Observe any late native action fault even if cancellation leaves
            // the await first. The caller isolates the interrupted GLPI page.
            _ = actionTask.ContinueWith(task => _ = task.Exception, CancellationToken.None,
                TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
            try
            {
                while (true)
                {
                    ct.ThrowIfCancellationRequested();
                    ThrowIfFailed();
                    if (actionTask.IsCompleted)
                    {
                        try { await actionTask; }
                        catch (Exception error) when (error is TimeoutException or PlaywrightException)
                        {
                            bool sent;
                            lock (_gate) sent = _requests.Values.Any(request => request.Sequence > waiter.Sequence && request.Command && Owned(request));
                            if (!sent) throw;
                            // The command reached GLPI. Waiting for its actual
                            // response is safe; sending the command again is not.
                        }
                        if (waiter.Completion.Task.IsCompleted)
                        {
                            ThrowIfFailed();
                            var response = await waiter.Completion.Task;
                            bool finished;
                            lock (_gate)
                                finished = _requests.TryGetValue(response.Request, out var matched)
                                    && !_requests.Values.Any(request => request.Chain == matched.Chain && request.Pending);
                            // Response headers do not prove that GLPI finished
                            // rendering or persisting. Keep the native frame
                            // alive until the response/redirect chain completes.
                            if (finished) return response;
                        }
                        if (!CanWait)
                            throw new InvalidOperationException($"GLPI ne montre plus de progression pendant {_phase}, sans requête native en cours. L’ajout n’est pas confirmé ; vérifier la vue personnelle avant de relancer.");
                    }
                    else _ = CanWait; // Report active work and detect native failures while the action settles.
                    await Task.Delay(120, ct);
                }
            }
            finally { lock (_gate) _waiters.Remove(waiter); }
        }

        public void Dispose()
        {
            lock (_gate)
            {
                if (_disposed) return;
                _disposed = true;
                _page.Request -= OnRequest;
                _page.Response -= OnResponse;
                _page.RequestFinished -= OnRequestFinished;
                _page.RequestFailed -= OnRequestFailed;
                _requests.Clear(); _waiters.Clear();
            }
        }
    }
}
